// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && collectAmount > 0);
        vm.assume(depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);

        // initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);
        uint256 expectedBalance = balanceBefore - collectAmount;

        // clear caller's ether so Collect can succeed with a simple call
        vm.deal(caller, 0);

        vm.prank(caller);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.balances(caller);

        assertTrue(balanceAfter == expectedBalance);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address caller) public {
        // Admissible domain: depositAmt > 0 to ensure a Deposit occurs, collectAmt <= depositAmt to allow Clean Collect,
        // caller is not the zero address, and we require MinSum = 0 so Collect isn't blocked by a minimum.
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt <= depositAmt);
        vm.assume(caller != address(0));
        // Bound depositAmt to avoid overflow in sum (uint256 max ~ 1e77) and keep it reasonably fuzzable
        depositAmt = bound(depositAmt, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0)); // irrelevant LogFile, never called during Collect assertions
        c.Initialized();

        // Record total tracked balance before any operation
        uint256 sumBefore = c.balances(caller);

        // 1. Deposit
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // 2. Collect
        vm.prank(caller);
        c.Collect(collectAmt);

        // After Deposit+Collect, the caller's balance (and the only balance in the system)
        // should reflect the net change.
        uint256 balanceAfter = c.balances(caller);

        // Correct rule: balanceAfter == sumBefore + depositAmt - collectAmt
        // Buggy version: depositAmt never added, so balanceAfter == sumBefore - collectAmt (when sumBefore >= collectAmt)
        // The rule target: the difference between final balance and initial balance must equal the net added amount.
        assertTrue(balanceAfter == sumBefore + depositAmt - collectAmt);
    }
}

