        collectAmount = bound(collectAmount, 1, type(uint128).max);
        depositAmount = bound(depositAmount, collectAmount + 1, type(uint128).max);

        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        vm.prank(sender);
        c.Collect(collectAmount);

