// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, address sender1, address sender2) public {
        vm.assume(sender1 != address(0));
        vm.assume(sender2 != address(0));
        vm.assume(sender1 != sender2);
        vm.assume(deposit1 > 0 && deposit2 > 0);
        vm.assume(deposit1 + deposit2 >= deposit1);
        vm.assume(deposit1 + deposit2 >= deposit2);
        vm.assume(deposit1 <= type(uint256).max - deposit2);

        c.Initialized();
        c.SetMinSum(0);

        vm.deal(sender1, deposit1);
        vm.prank(sender1);
        c.Deposit{value: deposit1}();

        uint256 sumBefore = c.balances(sender1) + c.balances(sender2);

        vm.deal(sender2, deposit2);
        vm.prank(sender2);
        c.Deposit{value: deposit2}();

        uint256 sumAfter = c.balances(sender1) + c.balances(sender2);

        assertTrue(sumAfter == sumBefore + deposit2);
    }
}

