pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address caller) public {
        // 1. Restrict to admissible domain: depositAmount must be non-zero, caller must not be address zero or this contract
        vm.assume(depositAmount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        // also avoid overflow in balance addition check
        vm.assume(depositAmount <= type(uint256).max - c.balances(caller));

        // Initialize contract and set MinSum to 0 so Collect doesn't revert on insufficient balance
        c.SetMinSum(0);
        c.SetLogFile(address(0x1)); // dummy Log address, not used for property
        c.Initialized();

        // Record balance before deposit
        uint256 balanceBefore = c.balances(caller);

        // Make the deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // 2. No adversarial helper needed; we interact only with c.
        // 3. Assert the universal rule: after Deposit, caller's balance must equal prior balance + depositAmount
        assertEq(c.balances(caller), balanceBefore + depositAmount, "Deposit should increase balance");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) public { c = _c; }
    function test(address caller, uint256 depositAmount, uint256 initialBalance) public {
        require(initialBalance + depositAmount >= initialBalance);
        require(address(this).balance >= depositAmount);
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Deposit{value: 0}();
        uint256 prev = c.balances(caller);
        c.Deposit{value: depositAmount}();
        uint256 post = c.balances(caller);
        assert(post == prev + depositAmount);
    }
}

